package com.jarvis.ai.storage

import android.content.Context
import android.os.Environment
import java.io.File

data class ProjectMeta(
    val name: String,
    val path: String,
    val htmlContent: String,
    val lastModified: Long
)

/**
 * Mobile Project & Code Storage Manager for Project JARVIS.
 * Saves websites, python scripts, and HTML files generated by JARVIS directly onto mobile storage.
 */
class ProjectFileManager(private val context: Context) {

    private val baseProjectsDir: File
        get() {
            val externalDir = context.getExternalFilesDir(Environment.DIRECTORY_DOCUMENTS)
            val dir = File(externalDir ?: context.filesDir, "JarvisProjects")
            if (!dir.exists()) {
                dir.mkdirs()
            }
            return dir
        }

    /**
     * Saves a generated web project with index.html to phone storage.
     */
    fun saveWebProject(projectName: String, htmlContent: String): File {
        val sanitizedName = projectName.trim().replace(Regex("[^a-zA-Z0-9_-]"), "_")
        val projectFolder = File(baseProjectsDir, sanitizedName)
        if (!projectFolder.exists()) {
            projectFolder.mkdirs()
        }

        val indexHtml = File(projectFolder, "index.html")
        indexHtml.writeText(htmlContent)
        return indexHtml
    }

    /**
     * Lists all saved projects on the mobile device.
     */
    fun listProjects(): List<ProjectMeta> {
        val list = mutableListOf<ProjectMeta>()
        val files = baseProjectsDir.listFiles() ?: return list

        for (folder in files) {
            if (folder.isDirectory) {
                val indexHtml = File(folder, "index.html")
                if (indexHtml.exists()) {
                    list.add(
                        ProjectMeta(
                            name = folder.name,
                            path = indexHtml.absolutePath,
                            htmlContent = indexHtml.readText(),
                            lastModified = indexHtml.lastModified()
                        )
                    )
                }
            }
        }
        return list.sortedByDescending { it.lastModified }
    }
}
